property.value:
//ClassDeclaration/ClassBody
    [
     count(MethodDeclaration[
        @Visibility = 'public'
        and
        not (
               (starts-with(@Name,'get') or starts-with(@Name,'set') or starts-with(@Name,'is'))
               and
               count(Block/*) <= 1
           )
     ]) > $maxmethods
  ]
